const o=window.matchMedia("(prefers-reduced-motion: reduce)").matches,t=document.querySelectorAll(".reveal");if(o||!("IntersectionObserver"in window))t.forEach(e=>e.classList.add("in"));else{const e=new IntersectionObserver(r=>{r.forEach(s=>{s.isIntersecting&&(s.target.classList.add("in"),e.unobserve(s.target))})},{rootMargin:"0px 0px -12% 0px",threshold:.1});t.forEach(r=>e.observe(r))}
